<?php use app\services\{Ui,Audit};use app\models\User;use yii\helpers\Html;$this->title='Amallar jurnali';$request=Yii::$app->request;$filters=$request->get();unset($filters['r'],$filters['page']); ?>
<div class="page-heading"><div><span class="eyebrow">SUPERADMINISTRATOR NAZORATI</span><h1>Amallar jurnali</h1><p>Kirish/chiqish, sozlamalar, arizalar, qarorlar va yuklab olishlar. Har sahifada 50 ta yozuv.</p></div><span class="pill"><?= (int)$total ?> TA YOZUV</span></div>
<section class="card"><nav class="actions" aria-label="Jurnal bo‘limlari"><?php foreach(['audit'=>'Barcha amallar','history'=>'Arizalar harakatlari'] as $key=>$label): ?><?= Html::a($label,['admin/audit','source'=>$key],['class'=>'button'.($source===$key?'':' secondary'),'aria-current'=>$source===$key?'page':null]) ?><?php endforeach ?></nav></section>
<section class="card"><?= Html::beginForm(['admin/audit'],'get',['class'=>'filters']) ?><?= Html::hiddenInput('source',$source) ?><?= Ui::input('Qidiruv','q',$request->get('q',''),'search',['maxlength'=>150,'placeholder'=>'Ism, login, amal yoki tafsilot']) ?><?= Ui::select('Amal','action',$request->get('action',''),[''=>'Barchasi']+array_combine($actions,array_map([Audit::class,'label'],$actions))) ?><?= Ui::input('Foydalanuvchi ID (0 — tizim)','actor',$request->get('actor',''),'number',['min'=>0]) ?><?= Ui::input('Boshlanish sanasi','from',$request->get('from',''),'date') ?><?= Ui::input('Tugash sanasi','to',$request->get('to',''),'date') ?><button class="button secondary">Ko‘rsatish</button><?= Html::endForm() ?>
<?php if(!$rows): ?><?= Ui::empty('Tanlangan shartlarga mos jurnal yozuvi yo‘q.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>ID / vaqt</th><th>Kim bajargan</th><th>Amal</th><th>Tafsilot</th></tr></thead><tbody>
<?php foreach($rows as $row):$payload=json_decode($row['details'],true);$identity=is_array($payload)?($payload['_context']['actor']??[]):[];$name=$identity['name']??$row['actor']??'Tizim';$role=$identity['role']??$row['role']??'';$details=$source==='history'?json_encode(['application_id'=>$row['application_id'],'step'=>$row['step'],'reason'=>$row['details'],'source'=>'Ariza harakatlari tarixi'],JSON_UNESCAPED_UNICODE):$row['details']; ?>
<tr data-audit-id="<?= (int)$row['id'] ?>"><td><b><?= $source==='history'?'R':'A' ?>#<?= (int)$row['id'] ?></b><small><?= date('d.m.Y H:i:s',$row['created_at']) ?></small></td><td><b><?= Ui::h($name) ?></b><small><?= Ui::h($identity['username']??$row['username']??'') ?> · ID <?= (int)$row['actor_id'] ?></small><small><?= Ui::h(User::ROLES[$role]??$role) ?></small></td><td><?= Ui::h(Audit::label($row['action'])) ?><small><?= Ui::h($row['action']) ?></small></td><td><details><summary>Tafsilotlarni ochish</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto"><?= Ui::h(Audit::format($details)) ?></pre></details></td></tr>
<?php endforeach ?></tbody></table></div><?php endif ?></section>
<div class="pagination"><?php if($page>1)echo Html::a('← Oldingi',array_merge(['admin/audit'],$filters,['page'=>$page-1]),['class'=>'button secondary']); ?><span><?= $page ?> / <?= max(1,(int)ceil($total/50)) ?></span><?php if($page*50<$total)echo Html::a('Keyingi →',array_merge(['admin/audit'],$filters,['page'=>$page+1]),['class'=>'button secondary']); ?></div>
